head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07405";
scwin.TR_JOB_INSERT = 2;  // 입력 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.NO_EXCEL_DATA = "해당데이터가 없습니다. 조회후 다운받으십시요.";  // 엑셀 다운로드 데이터 없음 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.lastJob = "";  // 업무 처리명(confirmJob 이 채우고 alertJobResult 가 읽는다 — as-is 전역 LastJob)
scwin.grd_Grid = null;
scwin.panel_page = null;
scwin.grd_List = null;
scwin.vSelectYear = "";
scwin.dts_List = null;
scwin.dts_Cod = null;
scwin.dts_BAS_YY = null;
scwin.dts_List2 = null;
scwin.dts_List3 = null;
scwin.pMenuID = undefined;
scwin.fn_list_sync = null;
scwin.fn_trs = null;
scwin.fn_setGrid = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.searchCode();
        await scwin.grdSearchCode();
        const firstYear = scwin.dts_BAS_YY.getCellData(1, "VALUE");
        slc_cmb_BAS_YY.setValue(firstYear);
        scwin.vSelectYear = firstYear;
        scwin.fn_list_sync();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07405.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pMenuID =$c.win.getProgramId(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07405' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.grd_Grid = $c.util.getComponent('grd_Grid');
        scwin.panel_page = $c.util.getComponent('panel_page');
        scwin.grd_List = $c.util.getComponent('grd_List');
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        scwin.dts_Cod = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cod')) : $c.util.getComponent('dts_Cod');
        scwin.dts_BAS_YY = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_BAS_YY')) : $c.util.getComponent('dts_BAS_YY');
        scwin.dts_List2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List2')) : $c.util.getComponent('dts_List2');
        scwin.dts_List3 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List3')) : $c.util.getComponent('dts_List3');
        scwin.fn_list_sync = scwin.tx_script_dts_List;
        scwin.fn_trs = scwin.sbm_trs_Save;
        scwin.fn_setGrid = scwin.tx_script_dts_List3;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07405.onpageload' });
    }
};

