    }
};

/**
 * @method
 * @name trs_Save_onsuccess
 * @description trs_Save onsuccess 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_onsuccess = async function () {
    try {
        await scwin.alertJobResult('S');
        await scwin.searchCode();
        if (scwin.vSelectYear == null && scwin.dts_BAS_YY.CountRow > 0) {
            slc_cmb_BAS_YY.setValue(scwin.dts_BAS_YY.getCellData(1, "VALUE"));
        }
        slc_cmb_BAS_YY.setValue(scwin.vSelectYear);
        scwin.fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldstf07405.trs_Save_onsuccess" });
    }
};

