 * @description btn_New 의 onclick 에서 dts_List 을(를) 행을 추가한다 외
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function () {
    try {
        scwin.dts_List.insertRow();
        const year = slc_cmb_BAS_YY.getValue();
        if (year !== "") {
            scwin.dts_List.setCellData(scwin.dts_List.getRowPosition(), "BAS_YY", year);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07405.btn_New_onclick' }); }
