 */
scwin.searchCode = async function () {
    const url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=CODE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstinvstg.specyvalu.instassgn.yearlist";

    await scwin.tx_script_dts_BAS_YY();
    let strCbd = "";
    for (j = 1; j <= scwin.dts_BAS_YY.CountRow; j++) {
        strCbd = strCbd + (strCbd === "" ? "" : ",") + scwin.dts_BAS_YY.getCellData(j, "VALUE") + "^" + scwin.dts_BAS_YY.getCellData(j, "TEXT");
    }
    if(slc_cmb_BAS_YY)slc_cmb_BAS_YY.CBData=strCbd;
};

