/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (!await scwin.confirmJob(TR_JOB)) {
            return;
        }
        scwin.fn_trs(scwin.TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function () {
    for (let i = 1, j = scwin.dts_List.CountRow; i <= j; i++) {
        const status = scwin.dts_List.getRowStatus(i);
        if (status === 1 || status === 3) {
            if (scwin.dts_List.getCellData(i, "SPECY_VALU_INST_CD") === " ") {
                await $c.win.alert(i + "번째행  " + "TCB기관명은 필수값입니다.");
                return false;
            }
            if (scwin.dts_List.getCellData(i, "BAS_YY") === "") {
                await $c.win.alert(i + "번째행  " + "연도는 필수값입니다.");
                return false;
            }
            if (scwin.dts_List.getCellData(i, "SORT_ORD") === "") {
                await $c.win.alert(i + "번째행  " + "배정순번은 필수값입니다.");
                return false;
            }
            if (scwin.dts_List.getCellData(i, "COL_ORD_SEQ") === "") {
                await $c.win.alert(i + "번째행  " + "컬럼순번은 필수값입니다.");
                return false;
            }
            let instCd, rowOrd, colOrd, basYy, instNm;
            let instCdIn, rowOrdIn, colOrdIn, instNmIn, basYyIn;
            instCd = scwin.dts_List.getCellData(i, "SPECY_VALU_INST_CD");
            rowOrd = scwin.dts_List.getCellData(i, "SORT_ORD");
            colOrd = scwin.dts_List.getCellData(i, "COL_ORD_SEQ");
            basYy = scwin.dts_List.getCellData(i, "BAS_YY");
            instNm = scwin.dts_Cod.getCellData(scwin.dts_Cod.NameValueRow("VALUE", instCd), "TEXT");
            for (let k = 1, l = scwin.dts_List.CountRow; k <= l; k++) {
                if (i === k) {
                    continue;
                }
                instCdIn = scwin.dts_List.getCellData(k, "SPECY_VALU_INST_CD");
                rowOrdIn = scwin.dts_List.getCellData(k, "SORT_ORD");
                colOrdIn = scwin.dts_List.getCellData(k, "COL_ORD_SEQ");
                instNmIn = scwin.dts_Cod.getCellData(scwin.dts_Cod.NameValueRow("VALUE", instCdIn), "TEXT");
                basYyIn = scwin.dts_List.getCellData(k, "BAS_YY");
                if (instCd === instCdIn && basYy === basYyIn) {
                    if (rowOrd === rowOrdIn) {
                        await $c.win.alert("'" + instNmIn + "' 중복된 배정순번이 존재합니다.");
                        return false;
                    }
                    if (colOrd !== colOrdIn) {
                        await $c.win.alert("'" + instNmIn + "' 컬럼순번이 다른값이 존재합니다.");
                        return false;
                    }
                }
                if (instCd !== instCdIn && basYy === basYyIn) {
                    if (colOrd === colOrdIn) {
                        await $c.win.alert("TCB기관별(" + instNm + " ," + instNmIn + ")중복된 컬럼순번이 존재합니다.");
                        return false;
                    }
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name setGrid2
 * @description set Grid2 처리
 * @returns {void}
 * @hidden N
 */
scwin.setGrid2 = function () {
    for (let i = 1, j = 12; i <= j; i++) {
        /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_List.getColumnInfo("COM_NM" + i, "Name") */
    }
    const maxRow = scwin.dts_List2.NameMax("SORT_ORD", 0, 0);
    const maxCol = scwin.dts_List2.NameMax("COL_ORD_SEQ", 0, 0);
    dts_List3.setBroadcast(false);
    for (let i = 1, j = maxRow; i <= j; i++) {
        scwin.dts_List3.insertRow();
    }
    dts_List3.setBroadcast(true, true);
    for (let i = 1, j = 12; i <= j; i++) {
        if (i <= maxCol) {
            /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_List.getColumnInfo("COM_NM" + i, "Show") */
        } else {
            /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_List.getColumnInfo("COM_NM" + i, "Show") */
        }
    }
    dts_List3.setBroadcast(false);
    for (let k = 1, l = maxCol; k <= l; k++) {
        for (let i = 1, j = maxRow; i <= j; i++) {
            const findRow = scwin.dts_List2.NameValueRow("MAKED_KEY", i + "_" + k);
            if (findRow > 0) {
                scwin.dts_List3.setCellData(i, "COM_NM" + k, scwin.dts_List2.getCellData(findRow, "ASSGN_COM_NM"));
                let grdHeadName = scwin.grd_List.getColumnInfo("COM_NM" + k, "Name");
                /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_List.getColumnInfo("COM_NM" + k, "Name") */
            }
        }
    }
    dts_List3.setBroadcast(true, true);
    for (let i = 1, j = 12; i <= j; i++) {
        grdHeadName = scwin.grd_List.getColumnInfo("COM_NM" + i, "Name");
        if (grdHeadName.indexOf("배정회사") > -1) {
            /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_List.getColumnInfo("COM_NM" + i, "Show") */
        }
    }
    scwin.showTotalCount(maxRow, scwin.panel_page);
    void 0;
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name showTotalCount
 * @description 목록 총건수 표시(as-is 공통 FillGridHeaderTotalCnt — 패널 안에 「총건수: N」)
 * @param {*} count 건수
 * @param {*} panel 표시할 그룹 id 또는 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.showTotalCount = function (count, panel) {
    const comp = (typeof panel === "string") ? $c.util.getComponent(panel) : panel;
    if (comp && comp.render) {
        comp.render.innerHTML = '<span class="count">총건수: <strong>' + $c.num.formatNumber(count) + "</strong></span>";
    }
};

/**
 * @method
 * @name getModalCenterPos
 * @description 모달 창을 화면 중앙에 놓을 좌표(as-is 공통 fn_getModalCenterPos)
 * @param {*} opnFrm 여는 창(window)
 * @param {*} frmWth 창 너비
 * @param {*} frmHgt 창 높이
 * @returns {Object} { x, y }
 * @hidden N
 */
scwin.getModalCenterPos = function (opnFrm, frmWth, frmHgt) {
    return { x: window.screen.width / 2 - opnFrm.screenLeft - frmWth / 2, y: window.screen.height / 2 - opnFrm.screenTop - frmHgt / 2 };
};

/**
 * @method
 * @name confirmJob
 * @description 업무 처리 확인 — "[저장] 하시겠습니까?" 확인창(as-is 공통 fn_isProcess 의 의미 보존 · pcc/fil 반입 후보)
 * @param {*} gubun 처리 구분(I 저장 · U 수정 · D 삭제 · S 제출 · R 해제 · DSCL 안내문작성)
 * @returns {Promise<Boolean>} 확인이면 true
 * @hidden N
 */
scwin.confirmJob = async function (gubun) {
    const job = { I: "저장", U: "수정", D: "삭제", S: "제출", R: "해제", DSCL: "안내문작성" }[gubun] || gubun;
    scwin.lastJob = job;  // 결과 알림(alertJobResult)이 같은 처리명을 쓴다 — as-is 전역 LastJob
    return $c.win.confirm("[" + job + "] 하시겠습니까?");
};

/**
 * @method
 * @name alertJobResult
 * @description 업무 처리 결과 알림 — S "[처리명] 처리 성공하였습니다." · S1 "성공적으로 처리되었습니다." · F "[처리명] 처리 실패하였습니다."
 * @param {*} gubun 결과 구분(S 성공 · S1 성공(처리명 없음) · F 실패)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertJobResult = async function (gubun) {
    const job = scwin.lastJob || "";
    if (gubun === "S") { await $c.win.alert("[" + job + "] 처리 성공하였습니다."); }
    else if (gubun === "S1") { await $c.win.alert("성공적으로 처리되었습니다."); }
    else if (gubun === "F") { await $c.win.alert("[" + job + "] 처리 실패하였습니다."); }
};
